<?php
if (!defined('ABSPATH')) exit;
/** Generic DARES P2000 bridge; P2000 plugin must emit the action or POST to this endpoint. */
final class Dares_Piket_P2000 {
 const OPT='dares_piket_p2000';
 static function settings(){return wp_parse_args((array)get_option(self::OPT,[]),['enabled'=>0,'audience'=>'active','secret'=>'']);}
 static function init(){add_action('init',[__CLASS__,'install']);add_action('dares_piket_p2000_prune',[__CLASS__,'prune']);if(!wp_next_scheduled('dares_piket_p2000_prune'))wp_schedule_event(time()+3600,'daily','dares_piket_p2000_prune');add_action('admin_menu',[__CLASS__,'menu']);add_action('admin_post_dares_piket_p2000_save',[__CLASS__,'save']);add_action('rest_api_init',[__CLASS__,'routes']);add_action('dares_p2000_alert',[__CLASS__,'local_alert'],10,1);}
 static function table(){global $wpdb;return $wpdb->prefix.'dares_piket_p2000_history';}
 static function install(){global $wpdb;if(get_option('dares_piket_p2000_history_schema')==='1')return;require_once ABSPATH.'wp-admin/includes/upgrade.php';$t=self::table();$collate=$wpdb->get_charset_collate();dbDelta("CREATE TABLE $t (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, event_hash char(64) NOT NULL, message text NOT NULL, event_at datetime NOT NULL, received_at datetime NOT NULL, push_count int NOT NULL DEFAULT 0, PRIMARY KEY (id), UNIQUE KEY event_hash (event_hash), KEY event_at (event_at)) $collate;");update_option('dares_piket_p2000_history_schema','1',false);}
 static function prune(){global $wpdb;$t=self::table();$days=max(7,min(365,(int)get_option('dares_piket_p2000_days',90)));$cut=gmdate('Y-m-d H:i:s',time()-$days*DAY_IN_SECONDS);$wpdb->query($wpdb->prepare("DELETE FROM $t WHERE received_at < %s",$cut));}
 static function history(){if(!is_user_logged_in())return '<p>Log in om DARES-meldingen te bekijken.</p>';$user=get_current_user_id();global $wpdb;$t=self::table();$filter=isset($_GET['dares_p2000_period'])?sanitize_key(wp_unslash($_GET['dares_p2000_period'])):'all';$min=$filter==='today'?gmdate('Y-m-d 00:00:00'):($filter==='week'?gmdate('Y-m-d H:i:s',time()-7*DAY_IN_SECONDS):'1970-01-01 00:00:00');$rows=$wpdb->get_results($wpdb->prepare("SELECT id,message,event_at,push_count FROM $t WHERE event_at >= %s ORDER BY id DESC LIMIT 100",$min));$read=array_map('intval',(array)get_user_meta($user,'dares_piket_p2000_read',true));$out='<section id="dares-p2000-history" class="dares-p2000-history"><h2>DARES P2000-meldingen</h2><p><a href="?dares-piket-pwa=app#dares-p2000-history">Alle</a> · <a href="?dares-piket-pwa=app&amp;dares_p2000_period=today#dares-p2000-history">Vandaag</a> · <a href="?dares-piket-pwa=app&amp;dares_p2000_period=week#dares-p2000-history">Afgelopen week</a></p>';
 if(!$rows)$out.='<p>Geen meldingen in deze periode.</p>';foreach($rows as $r){$new=!in_array((int)$r->id,$read,true);$out.='<article class="dares-p2000-item"><div><strong>'.($new?'● Nieuw':'DARES-melding').'</strong><time>'.esc_html(wp_date('d-m-Y H:i',strtotime($r->event_at.' UTC'))).'</time></div><p>'.esc_html($r->message).'</p>';if($new)$out.='<button type="button" data-dares-p2000-read="'.esc_attr($r->id).'">Markeer gelezen</button>';$out.='</article>';}$out.='</section>';return $out;}
 static function mark_read($request){if(!is_user_logged_in())return new WP_Error('not_logged_in','Log eerst in',['status'=>401]);$id=absint($request['id']);global $wpdb;$t=self::table();if(!$wpdb->get_var($wpdb->prepare("SELECT id FROM $t WHERE id=%d",$id)))return new WP_Error('not_found','Onbekende melding',['status'=>404]);$uid=get_current_user_id();$read=array_map('intval',(array)get_user_meta($uid,'dares_piket_p2000_read',true));$read[]=$id;$read=array_slice(array_values(array_unique($read)),-1000);update_user_meta($uid,'dares_piket_p2000_read',$read);return ['success'=>true];}
 static function menu(){add_submenu_page('dares-piketrooster','P2000 pushkoppeling','P2000 pushkoppeling','manage_options','dares-piket-p2000',[__CLASS__,'admin']);}
 static function admin(){if(!current_user_can('manage_options'))wp_die('Geen toegang');$o=self::settings();$endpoint=rest_url('dares-piket/v1/p2000-alert');echo '<div class="wrap"><h1>DARES P2000 → PWA push</h1><p>Alleen expliciet als DARES gemarkeerde meldingen worden doorgestuurd. De P2000-plugin moet hiervoor de WordPress-action <code>dares_p2000_alert</code> uitsturen of een HTTPS POST doen naar de onderstaande endpoint.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('dares_piket_p2000_save');echo '<input type="hidden" name="action" value="dares_piket_p2000_save"><p><label><input type="checkbox" name="enabled" value="1" '.checked($o['enabled'],1,false).'> DARES P2000-meldingen pushen</label></p><p>Ontvangers: <select name="audience"><option value="active" '.selected($o['audience'],'active',false).'>Alleen actieve piketmedewerker</option><option value="all" '.selected($o['audience'],'all',false).'>Alle aangemelde PWA-toestellen</option></select></p><p>Webhook URL: <code>'.esc_html($endpoint).'</code></p><p>Geheime koppelingssleutel (vertrouwelijk): <input class="regular-text" type="password" name="secret" value="" autocomplete="new-password" placeholder="Leeg laten om bestaande te behouden"></p><p>De sleutel wordt in de HTTP-header <code>X-Dares-P2000-Key</code> verstuurd. Bij lokale WordPress-action is geen sleutel nodig. Deel deze sleutel nooit publiek.</p><button class="button button-primary">Opslaan</button></form></div>';}
 static function save(){if(!current_user_can('manage_options'))wp_die('Geen toegang');check_admin_referer('dares_piket_p2000_save');$o=self::settings();$o['enabled']=empty($_POST['enabled'])?0:1;$o['audience']=($_POST['audience']??'')==='all'?'all':'active';$secret=isset($_POST['secret'])?trim((string)wp_unslash($_POST['secret'])):'';if($secret!==''){if(strlen($secret)<24)wp_die('Gebruik een willekeurige geheime sleutel van minimaal 24 tekens.');$o['secret']=$secret;}update_option(self::OPT,$o,false);wp_safe_redirect(admin_url('admin.php?page=dares-piket-p2000'));exit;}
 static function routes(){register_rest_route('dares-piket/v1','/p2000-read/(?P<id>\d+)',['methods'=>'POST','permission_callback'=>function(){return is_user_logged_in();},'callback'=>[__CLASS__,'mark_read']]);register_rest_route('dares-piket/v1','/p2000-alert',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>[__CLASS__,'receive']]);}
 static function permission($req){$o=self::settings();if(!$o['enabled']||strlen($o['secret'])<24)return new WP_Error('disabled','Koppeling niet geconfigureerd',['status'=>403]);$provided=$req->get_header('x-dares-p2000-key');return is_string($provided)&&hash_equals($o['secret'],$provided);}
 static function receive($req){$data=$req->get_json_params();if(!is_array($data))return new WP_Error('format','JSON-object verwacht',['status'=>400]);return self::process($data);}
 static function local_alert($data){if(is_array($data))self::process($data);}
 static function process($data){$o=self::settings();if(!$o['enabled'])return ['sent'=>0,'disabled'=>true];if(empty($data['dares'])||!in_array($data['dares'],[true,1,'1'],true))return new WP_Error('not_dares','Melding is niet als DARES gemarkeerd',['status'=>400]);
  $id=sanitize_text_field((string)($data['id']??''));$text=sanitize_text_field((string)($data['message']??''));if(!$id||strlen($id)>160||!$text)return new WP_Error('invalid','Melding-ID en berichttekst verplicht',['status'=>400]);$text=mb_substr($text,0,350);$key='dares_p2000_'.hash('sha256',$id);if(get_transient($key))return ['sent'=>0,'duplicate'=>true];
  global $wpdb;$table=self::table();self::install();$hash=hash('sha256',$id);$now=current_time('mysql',true);$wpdb->query($wpdb->prepare("INSERT IGNORE INTO $table (event_hash,message,event_at,received_at,push_count) VALUES (%s,%s,%s,%s,0)",$hash,$text,$now,$now));$history_id=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM $table WHERE event_hash=%s",$hash));
  $title='DARES P2000 melding';$count=0;
  if($o['audience']==='active'){$active=Dares_Piketrooster::global_current();if($active)$count=Dares_Piket_Push::person((int)$active->person_id,$title,$text,'p2000-'.substr(hash('sha256',$id),0,24));}
  else{global $wpdb;$users=$wpdb->get_col('SELECT DISTINCT user_id FROM '.Dares_Piket_Push::table());foreach($users as $uid)$count+=Dares_Piket_Push::user((int)$uid,$title,$text,'p2000-'.substr(hash('sha256',$id),0,24));}
  if($history_id)$wpdb->update($table,['push_count'=>$count],['id'=>$history_id],['%d'],['%d']);update_option('dares_piket_last_p2000_push',['at'=>time(),'count'=>$count,'history_id'=>$history_id],false);set_transient($key,1,7*DAY_IN_SECONDS);return ['sent'=>$count,'accepted'=>true,'history_id'=>$history_id];
 }
}
